<script setup>import{Head,Link}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';const props=defineProps({award:Object});const share=async()=>{const data={title:`${props.award.title} · Mandem`,text:props.award.description,url:location.href};if(navigator.share)await navigator.share(data);else await navigator.clipboard.writeText(`${data.title}\n${data.text}\n${data.url}`)};</script><template><Head :title="award.title"/><AppLayout><Link href="/hall-of-fame" class="text-sm font-bold text-[#697970]">← Hall of Fame</Link><div class="mx-auto mt-7 max-w-2xl"><div class="relative overflow-hidden rounded-[2rem] bg-[#0c271b] p-9 text-white shadow-2xl sm:p-14"><div class="absolute -right-20 -top-20 size-70 rounded-full bg-[#f4d35e]/10"></div><div class="absolute -bottom-28 -left-20 size-72 rounded-full bg-emerald-400/10"></div><div class="relative"><div class="flex items-center justify-between"><span class="grid size-12 place-items-center rounded-xl bg-[#f4d35e] font-black text-[#173425]">M</span><span class="label !text-white/40">Gameweek honour</span></div><div class="py-20 text-center"><span class="text-6xl">🏆</span><p class="label mt-7 !text-[#f4d35e]">{{award.title}}</p><h1 class="mt-3 text-5xl font-black tracking-tight">{{award.entry.manager_name}}</h1><p class="mx-auto mt-4 max-w-md text-lg text-white/60">{{award.description}}</p></div><div class="flex justify-between border-t border-white/10 pt-6 text-xs text-white/40"><span>MANDEM FANTASY CLUB</span><span>THE NUMBERS DON'T LIE</span></div></div></div><button @click="share" class="btn-primary mt-5 w-full">Share this honour ↗</button><p class="mt-3 text-center text-xs text-[#718078]">Uses your device share sheet, or copies a link when sharing is unavailable.</p></div></AppLayout></template>
